// Shared focus treatment for every dashboard SVG, including legacy charts.
function nearestChartPoints(points,x,y){if(!points.length)return [];const nearest=points.reduce((a,b)=>Math.abs(b.x-x)<Math.abs(a.x-x)?b:a),column=points.filter(p=>Math.abs(p.x-nearest.x)<.5);return column.sort((a,b)=>Math.abs(a.y-y)-Math.abs(b.y-y));}
const focusChartBind=bind;bind=function(){focusChartBind();document.getElementById('dashboardChartTip')?.remove();const tip=document.createElement('div');tip.id='dashboardChartTip';tip.setAttribute('role','tooltip');tip.className='dashboard-chart-tip';tip.hidden=true;document.body.appendChild(tip);document.querySelectorAll('#content svg').forEach(svg=>{const circles=[...svg.querySelectorAll('circle')].map(el=>({el,x:+el.getAttribute('cx'),y:+el.getAttribute('cy')})),regions=[...svg.querySelectorAll('[data-chart-tip],[data-review-chart]')],bars=[...svg.querySelectorAll('g')].filter(g=>g.querySelector('title')&&g.querySelector('rect'));if(!circles.length&&!bars.length)return;const ns='http://www.w3.org/2000/svg',layer=document.createElementNS(ns,'g');layer.setAttribute('pointer-events','none');layer.setAttribute('aria-hidden','true');svg.appendChild(layer);let activeBar=null,focused=null;const clear=()=>{layer.replaceChildren();activeBar?.classList.remove('dashboard-bar-focused');activeBar=null;tip.hidden=true;};const add=(tag,attrs)=>{const e=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);layer.appendChild(e);};const position=(text,event,anchor)=>{tip.textContent=text;tip.hidden=false;const r=anchor.getBoundingClientRect(),px=event?.clientX??r.left+r.width/2,py=event?.clientY??r.top;tip.style.left=Math.max(12,Math.min(px+18,window.innerWidth-tip.offsetWidth-12))+'px';tip.style.top=Math.max(12,Math.min(py+18,window.innerHeight-tip.offsetHeight-12))+'px';};const show=(x,y,event,target)=>{clear();if(circles.length){if(regions.includes(target)){const rx=+target.getAttribute('x'),rw=+target.getAttribute('width');if(!circles.some(p=>p.x>=rx&&p.x<=rx+rw)){position(target.getAttribute('data-chart-tip')||target.getAttribute('aria-label')||'No data supplied',event,target);return;}}const column=nearestChartPoints(circles,x,y),primary=column[0];if(!primary)return;const region=regions.find(r=>{const rx=+r.getAttribute('x'),rw=+r.getAttribute('width');return primary.x>=rx&&primary.x<=rx+rw;});const ys=circles.map(p=>p.y),top=Math.max(18,Math.min(...ys)-15),bottom=Math.max(...ys)+15;add('line',{x1:primary.x,x2:primary.x,y1:top,y2:bottom,stroke:'#536b7a','stroke-width':1.5,'stroke-dasharray':'4 4'});column.forEach((p,i)=>{add('circle',{cx:p.x,cy:p.y,r:i===0?9:7,fill:'#fff',stroke:p.el.getAttribute('fill')||'#087f8c','stroke-width':i===0?3:2});add('circle',{cx:p.x,cy:p.y,r:3,fill:p.el.getAttribute('fill')||'#087f8c'});});const text=region?.getAttribute('data-chart-tip')||region?.getAttribute('aria-label')||column.map(p=>p.el.querySelector('title')?.textContent||p.el.getAttribute('aria-label')||'').filter(Boolean).join('\n');if(text)position(text,event,primary.el);}else{const bar=target?.closest('g');if(!bar||!bars.includes(bar))return;activeBar=bar;bar.classList.add('dashboard-bar-focused');position(bar.querySelector('title').textContent,event,bar);}};regions.forEach(r=>{r.onpointerenter=r.onpointermove=r.onpointerleave=r.onfocus=r.onblur=null;});circles.forEach(p=>{if(!regions.length){p.el.setAttribute('tabindex','0');p.el.setAttribute('role','img');p.el.setAttribute('aria-label',p.el.querySelector('title')?.textContent||'Chart data point');}});bars.forEach(b=>{if(!b.hasAttribute('tabindex'))b.setAttribute('tabindex','0');});svg.addEventListener('pointermove',event=>{const matrix=svg.getScreenCTM();if(!matrix)return;const p=svg.createSVGPoint();p.x=event.clientX;p.y=event.clientY;const local=p.matrixTransform(matrix.inverse());show(local.x,local.y,event,event.target);});svg.addEventListener('pointerleave',()=>{if(!focused)clear();});svg.addEventListener('focusin',event=>{focused=event.target;const el=event.target,point=circles.find(p=>p.el===el),index=el.getAttribute('data-review-point'),month=el.getAttribute('data-economics-chart');let x=point?.x,y=point?.y;if(x===undefined&&regions.includes(el)){const rx=+el.getAttribute('x'),rw=+el.getAttribute('width');x=circles.find(p=>p.x>=rx&&p.x<=rx+rw)?.x??(rx+rw/2);y=circles.find(p=>Math.abs(p.x-x)<.5)?.y??0;}show(x??0,y??0,null,el);});svg.addEventListener('focusout',()=>{focused=null;clear();});svg.addEventListener('keydown',event=>{if(event.key==='Escape')clear();});svg.addEventListener('click',()=>clear());});};
